<?php require __DIR__.'/includes/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$u=input_filter($_POST,'username');$p=$_POST['password']??'';if(!preg_match('/^[A-Za-z0-9_]{3,50}$/D',$u)||!is_string($p)||strlen($p)<8||strlen($p)>72||str_contains($p,"\0")){$error='Use 3–50 letters, digits or underscores and a password of 8–72 bytes.';}else{try{$s=$db->prepare('INSERT INTO song_users(username,password) VALUES (?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);redirect('login.php');}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$error='Username unavailable.';}}}render('auth.twig',['heading'=>'Register','error'=>$error,'register'=>true]);
